1. using System;
2. using System.Collections.Generic;
3. using System.Globalization;
4. using System.IO;
5. using System.Linq;
6. using LegacyTradeReconciliation.Domain;
7. 
8. namespace LegacyTradeReconciliation
9. {
10.     public sealed class CsvFileGateway
11.     {
12.         public List<TradeRecord> LoadTrades(string inputDirectory)
13.         {
14.             return ReadRequiredLines(inputDirectory, BatchConfiguration.TradesFileName)
15.                 .Skip(1)
16.                 .Where(line => !string.IsNullOrWhiteSpace(line))
17.                 .Select(ParseTrade)
18.                 .ToList();
19.         }
20. 
21.         public List<PositionRecord> LoadPositions(string inputDirectory)
22.         {
23.             return ReadRequiredLines(inputDirectory, BatchConfiguration.PositionsFileName)
24.                 .Skip(1)
25.                 .Where(line => !string.IsNullOrWhiteSpace(line))
26.                 .Select(ParsePosition)
27.                 .ToList();
28.         }
29. 
30.         public List<SettlementRecord> LoadSettlements(string inputDirectory)
31.         {
32.             return ReadRequiredLines(inputDirectory, BatchConfiguration.SettlementsFileName)
33.                 .Skip(1)
34.                 .Where(line => !string.IsNullOrWhiteSpace(line))
35.                 .Select(ParseSettlement)
36.                 .ToList();
37.         }
38. 
39.         public List<ManualOverrideRecord> LoadOverrides(string inputDirectory)
40.         {
41.             string path = Path.Combine(inputDirectory, BatchConfiguration.OverridesFileName);
42.             if (!File.Exists(path))
43.             {
44.                 return new List<ManualOverrideRecord>();
45.             }
46. 
47.             return File.ReadAllLines(path)
48.                 .Skip(1)
49.                 .Where(line => !string.IsNullOrWhiteSpace(line))
50.                 .Select(ParseOverride)
51.                 .ToList();
52.         }
53. 
54.         public void WriteMatchedTrades(string outputDirectory, IReadOnlyCollection<MatchedTradeRecord> matchedTrades)
55.         {
56.             string path = Path.Combine(outputDirectory, BatchConfiguration.MatchedTradesFileName);
57.             var lines = new List<string>
58.             {
59.                 "trade_id,status,account,instrument,quantity,settlement_date,currency,position_id,settlement_id,override_note"
60.             };
61. 
62.             lines.AddRange(matchedTrades
63.                 .OrderBy(record => record.TradeId, StringComparer.Ordinal)
64.                 .Select(record => string.Join(",",
65.                     record.TradeId,
66.                     record.Status,
67.                     record.Account,
68.                     record.Instrument,
69.                     FormatDecimal(record.Quantity),
70.                     record.SettlementDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
71.                     record.Currency,
72.                     record.PositionId ?? string.Empty,
73.                     record.SettlementId ?? string.Empty,
74.                     record.OverrideNote ?? string.Empty)));
75. 
76.             File.WriteAllLines(path, lines);
77.         }
78. 
79.         public void WriteBreakQueue(string outputDirectory, IReadOnlyCollection<BreakRecord> breakQueue)
80.         {
81.             string path = Path.Combine(outputDirectory, BatchConfiguration.BreakQueueFileName);
82.             var lines = new List<string>
83.             {
84.                 "trade_id,account,instrument,quantity,settlement_date,currency,reasons,position_id,settlement_id"
85.             };
86. 
87.             lines.AddRange(breakQueue
88.                 .OrderBy(record => record.TradeId, StringComparer.Ordinal)
89.                 .ThenBy(record => record.Reasons, StringComparer.Ordinal)
90.                 .Select(record => string.Join(",",
91.                     record.TradeId,
92.                     record.Account,
93.                     record.Instrument,
94.                     FormatDecimal(record.Quantity),
95.                     record.SettlementDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
96.                     record.Currency,
97.                     record.Reasons,
98.                     record.PositionId ?? string.Empty,
99.                     record.SettlementId ?? string.Empty)));
100. 
101.             File.WriteAllLines(path, lines);
102.         }
103. 
104.         public void WriteEndOfDayReport(string outputDirectory, string reportText)
105.         {
106.             File.WriteAllText(Path.Combine(outputDirectory, BatchConfiguration.EndOfDayReportFileName), reportText);
107.         }
108. 
109.         private static string[] ReadRequiredLines(string inputDirectory, string fileName)
110.         {
111.             return File.ReadAllLines(Path.Combine(inputDirectory, fileName));
112.         }
113. 
114.         private static TradeRecord ParseTrade(string line)
115.         {
116.             string[] cells = Split(line, 7);
117.             return new TradeRecord
118.             {
119.                 TradeId = cells[0],
120.                 Account = cells[1],
121.                 Instrument = cells[2],
122.                 Quantity = ParseDecimal(cells[3]),
123.                 SettlementDate = ParseDate(cells[4]),
124.                 Currency = cells[5],
125.                 NetAmount = ParseDecimal(cells[6])
126.             };
127.         }
128. 
129.         private static PositionRecord ParsePosition(string line)
130.         {
131.             string[] cells = Split(line, 6);
132.             return new PositionRecord
133.             {
134.                 PositionId = cells[0],
135.                 Account = cells[1],
136.                 Instrument = cells[2],
137.                 Quantity = ParseDecimal(cells[3]),
138.                 SettlementDate = ParseDate(cells[4]),
139.                 Currency = cells[5]
140.             };
141.         }
142. 
143.         private static SettlementRecord ParseSettlement(string line)
144.         {
145.             string[] cells = Split(line, 7);
146.             return new SettlementRecord
147.             {
148.                 SettlementId = cells[0],
149.                 Account = cells[1],
150.                 Instrument = cells[2],
151.                 Quantity = ParseDecimal(cells[3]),
152.                 SettlementDate = ParseDate(cells[4]),
153.                 Currency = cells[5],
154.                 CashAmount = ParseDecimal(cells[6])
155.             };
156.         }
157. 
158.         private static ManualOverrideRecord ParseOverride(string line)
159.         {
160.             string[] cells = Split(line, 4);
161.             return new ManualOverrideRecord
162.             {
163.                 TradeId = cells[0],
164.                 Action = cells[1],
165.                 Note = cells[2],
166.                 ApprovedBy = cells[3]
167.             };
168.         }
169. 
170.         private static string[] Split(string line, int expectedCellCount)
171.         {
172.             string[] cells = line.Split(',');
173.             if (cells.Length != expectedCellCount)
174.             {
175.                 throw new InvalidDataException("Unexpected csv format: " + line);
176.             }
177. 
178.             return cells.Select(value => value.Trim()).ToArray();
179.         }
180. 
181.         private static decimal ParseDecimal(string value)
182.         {
183.             return decimal.Parse(value, NumberStyles.Number | NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture);
184.         }
185. 
186.         private static DateTime ParseDate(string value)
187.         {
188.             return DateTime.ParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture);
189.         }
190. 
191.         private static string FormatDecimal(decimal value)
192.         {
193.             return value.ToString("0.####", CultureInfo.InvariantCulture);
194.         }
195.     }
196. }
