namespace TradeReconciliation.Core.Domain;

/// <summary>Trade as ingested from <c>trades.csv</c>. Raw (un-normalized) values are retained.</summary>
public sealed class TradeRecord
{
    public required string TradeId { get; init; }

    public required string Account { get; init; }

    public required string Instrument { get; init; }

    public required decimal Quantity { get; init; }

    public required DateOnly SettlementDate { get; init; }

    public required string Currency { get; init; }

    public required decimal NetAmount { get; init; }
}

/// <summary>Custodian position as ingested from <c>positions.csv</c>.</summary>
public sealed class PositionRecord
{
    public required string PositionId { get; init; }

    public required string Account { get; init; }

    public required string Instrument { get; init; }

    public required decimal Quantity { get; init; }

    public required DateOnly SettlementDate { get; init; }

    public required string Currency { get; init; }
}

/// <summary>Settlement instruction as ingested from <c>settlements.csv</c>.</summary>
public sealed class SettlementRecord
{
    public required string SettlementId { get; init; }

    public required string Account { get; init; }

    public required string Instrument { get; init; }

    public required decimal Quantity { get; init; }

    public required DateOnly SettlementDate { get; init; }

    public required string Currency { get; init; }

    public required decimal CashAmount { get; init; }
}

/// <summary>
/// Manual override instruction as ingested from <c>overrides.csv</c>.
/// </summary>
/// <remarks>
/// This is deliberately a reference type without value equality. Duplicate instructions for the
/// same trade are distinct pieces of evidence (AMB-2 / REQ-4) and must never collapse into one row,
/// so identity is reference identity.
/// </remarks>
public sealed class ManualOverrideRecord
{
    public required string TradeId { get; init; }

    public required string Action { get; init; }

    public required string Note { get; init; }

    public required string ApprovedBy { get; init; }
}

namespace TradeReconciliation.Core.Domain;

/// <summary>A row of <c>matched-trades.csv</c>. All identity fields are normalized.</summary>
public sealed class MatchedTradeRecord
{
    public required string TradeId { get; init; }

    public required string Status { get; init; }

    public required string Account { get; init; }

    public required string Instrument { get; init; }

    public required decimal Quantity { get; init; }

    public required DateOnly SettlementDate { get; init; }

    public required string Currency { get; init; }

    public string? PositionId { get; init; }

    public string? SettlementId { get; init; }

    public string? OverrideNote { get; init; }
}

/// <summary>A row of <c>break-queue.csv</c>. All identity fields are normalized.</summary>
public sealed class BreakRecord
{
    public required string TradeId { get; init; }

    public required string Account { get; init; }

    public required string Instrument { get; init; }

    public required decimal Quantity { get; init; }

    public required DateOnly SettlementDate { get; init; }

    public required string Currency { get; init; }

    /// <summary>Pipe-delimited, de-duplicated, ordinally sorted break reason codes.</summary>
    public required string Reasons { get; init; }

    public string? PositionId { get; init; }

    public string? SettlementId { get; init; }

    /// <summary>
    /// True only when concrete position and settlement counterparts exist for the trade.
    /// A manual override can never manufacture a match for a break where this is false (INV-3).
    /// </summary>
    public required bool CanManualOverride { get; init; }
}

/// <summary>A row of <c>run-ledger.csv</c>.</summary>
public sealed class RunLedgerEntry
{
    public required DateOnly BusinessDate { get; init; }

    public required string InputSignature { get; init; }

    public required int TotalTradesRead { get; init; }

    public required int OpenBreakCount { get; init; }

    public required int MatchedCount { get; init; }
}

namespace TradeReconciliation.Core.Domain;

/// <summary>Break reason codes emitted in the <c>reasons</c> column of <c>break-queue.csv</c>.</summary>
public static class BreakReasons
{
    public const string DuplicateTradeId = "DuplicateTradeId";
    public const string TradeValueOutOfBounds = "TradeValueOutOfBounds";
    public const string MissingPosition = "MissingPosition";
    public const string MissingSettlement = "MissingSettlement";
    public const string PositionSettlementDateMismatch = "PositionSettlementDateMismatch";
    public const string PositionCurrencyMismatch = "PositionCurrencyMismatch";
    public const string PositionQuantitySignMismatch = "PositionQuantitySignMismatch";
    public const string PositionQuantityOutOfTolerance = "PositionQuantityOutOfTolerance";
    public const string SettlementDateMismatch = "SettlementDateMismatch";
    public const string SettlementCurrencyMismatch = "SettlementCurrencyMismatch";
    public const string SettlementQuantitySignMismatch = "SettlementQuantitySignMismatch";
    public const string SettlementQuantityOutOfTolerance = "SettlementQuantityOutOfTolerance";
    public const string SettlementAmountOutOfTolerance = "SettlementAmountOutOfTolerance";

    /// <summary>
    /// Reasons that describe a structurally absent or ineligible trade. A break carrying any of
    /// these can never be resolved by a manual override because no concrete counterpart exists.
    /// </summary>
    public static bool BlocksManualOverride(string reason) =>
        reason is MissingPosition or MissingSettlement or DuplicateTradeId or TradeValueOutOfBounds;
}

/// <summary>Values emitted in the <c>status</c> column of <c>matched-trades.csv</c>.</summary>
public static class MatchStatuses
{
    public const string Matched = "Matched";
    public const string ManualOverrideMatched = "ManualOverrideMatched";
    public const string ManualOverrideSuppressed = "ManualOverrideSuppressed";
}

/// <summary>Normalized (trimmed, upper-cased) manual override actions.</summary>
public static class OverrideActions
{
    public const string ForceMatch = "FORCEMATCH";
    public const string SuppressBreak = "SUPPRESSBREAK";
}

